import{c as e,Q as a,j as o,m as r}from"./chunks/framework.BXc4yaFE.js";const g=JSON.parse('{"title":"Auto-load 完整測試框架藍圖 + 多輪修正計劃","description":"","frontmatter":{"title":"Auto-load 完整測試框架藍圖 + 多輪修正計劃","date":"2026-06-04T00:00:00.000Z","status":"藍圖 + 安全機械缺口本 session APPLY；R1-R12 打包 gate out-of-band","btw":"規劃 auto-load 在不影響效能/功能下完整測試 + 調整","decision":"先建測試能力 → gated 調整（使用者定奪）","goal":"依報告 + Harness Loop 多輪修正直到全部 auto-load 修正完畢","type":"blueprint + execution-plan"},"headers":[],"relativePath":"research/reports/archive/2026-06-04-autoload-test-framework-blueprint.md","filePath":"research/reports/archive/2026-06-04-autoload-test-framework-blueprint.md","lastUpdated":1780842316000}'),s={name:"research/reports/archive/2026-06-04-autoload-test-framework-blueprint.md"};function d(n,t,i,l,h,c){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="auto-load-完整測試框架藍圖-多輪修正計劃" tabindex="-1">Auto-load 完整測試框架藍圖 + 多輪修正計劃 <a class="header-anchor" href="#auto-load-完整測試框架藍圖-多輪修正計劃" aria-label="Permalink to &quot;Auto-load 完整測試框架藍圖 + 多輪修正計劃&quot;">​</a></h1><blockquote><p>走 Harness Loop。<strong>核心修正</strong>（advisor 校準）：建測試<strong>只 stage protection 不 deliver</strong>——R1-R12 遵守度 eval 不可 inline（須 per-model fresh session + sandbox），故 loop 終止條件<strong>不可定義為「R1-R12 re-encoded」</strong>。</p></blockquote><hr><h2 id="_0-loop-終止條件-§r4-機械可驗證" tabindex="-1">0. Loop 終止條件（§R4，機械可驗證） <a class="header-anchor" href="#_0-loop-終止條件-§r4-機械可驗證" aria-label="Permalink to &quot;0. Loop 終止條件（§R4，機械可驗證）&quot;">​</a></h2><p>「全部 auto-load 修正完畢」<strong>字面詮釋會指回剛 DEFER 的 §R re-encode</strong>（grep-only 驗證不足）。終態<strong>重定義</strong>為三條件全綠：</p><table tabindex="0"><thead><tr><th>#</th><th>終止條件</th><th>機械驗證</th></tr></thead><tbody><tr><td>T1</td><td>機械 test gates 就位且綠</td><td><code>measure.sh</code> byte gate exit 0 + §R header 存活檢查 PASS + healthcheck FAIL=0</td></tr><tr><td>T2</td><td>無待修事實錯誤</td><td>grep 確認 κ/cache/stale 已修（#451 + 本輪）</td></tr><tr><td>T3</td><td>R1-R12 re-encode <strong>打包</strong>（非執行）</td><td>計劃書 D1-D4 before/after + danger-table 就緒，明確 block 在 out-of-band eval + user gate</td></tr></tbody></table><p><strong>不接受</strong>「直到所有 §R 條文都 re-encode」當終止——那是 hacked goal（用不足驗證換 byte，違 adherence-first 研究結論 + advisor）。</p><hr><h2 id="_1-既有測試資產-observe-researcher-盤點-主對話抽驗-4-4-屬實" tabindex="-1">1. 既有測試資產（OBSERVE，researcher 盤點 + 主對話抽驗 4/4 屬實） <a class="header-anchor" href="#_1-既有測試資產-observe-researcher-盤點-主對話抽驗-4-4-屬實" aria-label="Permalink to &quot;1. 既有測試資產（OBSERVE，researcher 盤點 + 主對話抽驗 4/4 屬實）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>資產</th><th>功能</th><th>覆蓋維度</th><th>可 inline？</th></tr></thead><tbody><tr><td><code>healthcheck.sh</code></td><td>13 section 結構健檢（PASS 108/WARN 3/FAIL 0）</td><td>功能（@ 連結/CLAUDE.md 行數/on-demand 路徑）</td><td>✅</td></tr><tr><td><code>measure.sh</code></td><td>byte 量測 + 三段門檻文字</td><td>功能（byte）</td><td>✅ 但<strong>無 exit gate</strong></td></tr><tr><td><code>measure-cache.sh</code></td><td>cache_hit_rate（jq 確定性聚合）</td><td>效能（cache）</td><td>❌ 須 live transcript</td></tr><tr><td><code>eval-score-behavioral.sh</code></td><td>task07/08 確定性 scorer</td><td>遵守度</td><td>✅ scorer / ❌ transcript 須 out-of-band</td></tr><tr><td><code>test-block-dangerous.sh</code></td><td>hook allow/block 單元測試</td><td>功能（hook 行為）</td><td>✅</td></tr><tr><td>task-01..06（PGE）</td><td>規則知識/修改/分析 eval</td><td>遵守度</td><td>❌ LLM 評分須委派</td></tr><tr><td>task-07/08 + RUNBOOK</td><td>ask-rate/fan-out behavioral</td><td>遵守度</td><td>❌ 須 per-model fresh + sandbox</td></tr><tr><td>cold-start hook 數字</td><td>7 hooks 實測 ms（一次性）</td><td>效能</td><td>❌ 無可重跑腳本</td></tr></tbody></table><hr><h2 id="_2-缺口-identify-scope-限-§r-外安全機械項" tabindex="-1">2. 缺口（IDENTIFY，scope 限 §R 外安全機械項） <a class="header-anchor" href="#_2-缺口-identify-scope-限-§r-外安全機械項" aria-label="Permalink to &quot;2. 缺口（IDENTIFY，scope 限 §R 外安全機械項）&quot;">​</a></h2><p>advisor 校準：大部分能力<strong>已存在</strong>，只補真缺口，<strong>不重建</strong> eval harness。</p><table tabindex="0"><thead><tr><th>缺口</th><th>嚴重</th><th>本 session？</th><th>落點（離 hot path）</th></tr></thead><tbody><tr><td>G-A：<code>measure.sh</code> 無 byte cap exit gate</td><td>中</td><td>✅ APPLY</td><td>measure.sh 加 exit 斷言</td></tr><tr><td>G-B：§R1–§R12 header 存活無自動驗證</td><td>中</td><td>✅ APPLY</td><td><strong>measure.sh / standalone</strong>（<strong>不放 healthcheck</strong>——已佔 pre-commit 96%，違「不影響效能」）</td></tr><tr><td>G-C：hook 計時無可重跑腳本</td><td>低</td><td>✅ APPLY</td><td>standalone <code>scripts/measure-hook-timing.sh</code>（不 wire 進 hook）</td></tr><tr><td>G-D：task-07/08 verdict 未跑</td><td>中</td><td>❌ out-of-band</td><td>RUNBOOK 既有；須 instrumented session</td></tr><tr><td>G-E：auto-load 載入延遲量測</td><td>—</td><td>❌ <strong>不建</strong></td><td>cold-start 已證 auto-load 非瓶頸（cache→0.1×），建它是測非瓶頸</td></tr></tbody></table><p><strong>「不影響效能」字面遵守</strong>：① 新結構斷言<strong>不入任何 hook</strong>（off hot path）；② auto-load 非效能槓桿（cold-start 既證）→ 「不影響效能」近乎免費，因為 auto-load 本就不是 lever。</p><hr><h2 id="_3-多輪修正計劃-propose-→-逐輪-harness-loop" tabindex="-1">3. 多輪修正計劃（PROPOSE → 逐輪 Harness Loop） <a class="header-anchor" href="#_3-多輪修正計劃-propose-→-逐輪-harness-loop" aria-label="Permalink to &quot;3. 多輪修正計劃（PROPOSE → 逐輪 Harness Loop）&quot;">​</a></h2><h3 id="round-1-—-建安全機械-gate-§r-外-本-session" tabindex="-1">Round 1 — 建安全機械 gate（§R 外，本 session） <a class="header-anchor" href="#round-1-—-建安全機械-gate-§r-外-本-session" aria-label="Permalink to &quot;Round 1 — 建安全機械 gate（§R 外，本 session）&quot;">​</a></h3><ul><li><strong>R1.1 G-A</strong>：measure.sh 末尾加 <code>if total &gt; 19000: exit 1</code>（CI gate；保留 informational 輸出）。</li><li><strong>R1.2 G-B</strong>：建 §R header 存活檢查——驗 core.md 含 §R1-R5/§R7-R12（11）+ context-management 含 §R6。放 measure.sh 新 section 或 standalone。</li><li><strong>R1.3 G-C</strong>：建 <code>scripts/measure-hook-timing.sh</code>——可重跑量測 7 hooks ms（標方法學：n/dummy stdin/cache 狀態，依 Lesson 2026-06-03-C）。<strong>不 wire 進 hook</strong>。</li><li><strong>驗證</strong>：三腳本各自跑通 + healthcheck FAIL=0 不變 + measure.sh byte gate 對 18,455 exit 0、對 &gt;19000 exit 1（注入測試）。</li></ul><h3 id="round-2-—-終態確認-t1-t2-機械驗證" tabindex="-1">Round 2 — 終態確認（T1/T2 機械驗證） <a class="header-anchor" href="#round-2-—-終態確認-t1-t2-機械驗證" aria-label="Permalink to &quot;Round 2 — 終態確認（T1/T2 機械驗證）&quot;">​</a></h3><ul><li>跑全 gate 確認綠；grep 確認無待修事實錯誤（κ/cache/stale）。</li><li>量測新腳本對 pre-commit 效能 delta（證 §R 外 standalone 不影響 hot path）。</li></ul><h3 id="round-3-—-r1-r12-打包-t3-非執行" tabindex="-1">Round 3 — R1-R12 打包（T3，非執行） <a class="header-anchor" href="#round-3-—-r1-r12-打包-t3-非執行" aria-label="Permalink to &quot;Round 3 — R1-R12 打包（T3，非執行）&quot;">​</a></h3><ul><li>確認計劃書 D1-D4 before/after + danger-table 就緒（已在 2026-06-04-r1r12 計劃書）。</li><li>明確標：execute 須 instrumented session（task-07/08 fresh run）+ 一次一條（≤1 規則/cycle）+ user gate。</li><li><strong>本 session 不執行任何 §R 編輯。</strong></li></ul><hr><h2 id="_4-falsifiable-prediction-round-1" tabindex="-1">4. Falsifiable Prediction（Round 1） <a class="header-anchor" href="#_4-falsifiable-prediction-round-1" aria-label="Permalink to &quot;4. Falsifiable Prediction（Round 1）&quot;">​</a></h2><p><strong>改動</strong>：建 3 個 §R 外 standalone/measure.sh gate（不碰 auto-load 內容、不碰 hook/settings）。</p><p><strong>預測</strong>：</p><ol><li>measure.sh 對現況（18,455）exit 0；注入 &gt;19,000 樣本 exit 1；</li><li>§R header 檢查對現況 PASS（11 + R6）；注入刪 header 樣本 FAIL；</li><li>hook 計時腳本可重跑，輸出含方法學標注；</li><li>healthcheck FAIL == 基線（0）；新腳本<strong>不入 hook</strong> → pre-commit 效能 delta = 0；</li><li>auto-load 5 檔內容 byte <strong>不變</strong>（18,455）——本 round 只加測試，不改 auto-load。</li></ol><p><strong>REFUTED 處置</strong>：任一失守 → 修腳本（非改 auto-load）；腳本無法達標 → 回報不硬塞。</p><hr><h2 id="_5-不做什麼-範圍界線" tabindex="-1">5. 不做什麼（範圍界線） <a class="header-anchor" href="#_5-不做什麼-範圍界線" aria-label="Permalink to &quot;5. 不做什麼（範圍界線）&quot;">​</a></h2><ul><li>❌ 不執行任何 §R1-R12 re-encode（驗證不足 + 須 out-of-band + user gate）</li><li>❌ 不 wire 新檢查進 hook/settings.json（cold-start §5 gated scope；違「不影響效能」）</li><li>❌ 不建 auto-load 載入延遲量測（測非瓶頸，cold-start 已證）</li><li>❌ 不重建既有 eval harness（scorer/RUNBOOK 已存在）</li><li>❌ loop 不以「§R 全 re-encode」為終止（hacked goal）</li></ul><hr><h2 id="_6-2026-06-05-增量併入-gap-vote-三技能共識-3-真-gap" tabindex="-1">6. 2026-06-05 增量併入（gap-vote 三技能共識，3 真 gap） <a class="header-anchor" href="#_6-2026-06-05-增量併入-gap-vote-三技能共識-3-真-gap" aria-label="Permalink to &quot;6. 2026-06-05 增量併入（gap-vote 三技能共識，3 真 gap）&quot;">​</a></h2><blockquote><p><strong>方法</strong>：gap-vote（research-hub / overnight-research / autoresearch:reason 並行）對近期 corpus 找未併入 gap，2/3 共識 + <strong>主對話親自 grep 重驗 verbatim</strong>。本藍圖分得「測試框架 / observability / telemetry」相關 gap。皆為<strong>未來 gated 增建的論文接地</strong>，非本 loop 立即執行（本 loop 終態 T1/T2/T3 已綠）。</p></blockquote><h3 id="補充-g-f-telemetry-讀寫不對稱可抓-pass-rate-抓不到的靜默-bug-harbor-arxiv-2604-20938" tabindex="-1">補充 G-F：telemetry 讀寫不對稱可抓 pass-rate 抓不到的靜默 bug（HARBOR，arXiv:2604.20938） <a class="header-anchor" href="#補充-g-f-telemetry-讀寫不對稱可抓-pass-rate-抓不到的靜默-bug-harbor-arxiv-2604-20938" aria-label="Permalink to &quot;補充 G-F：telemetry 讀寫不對稱可抓 pass-rate 抓不到的靜默 bug（HARBOR，arXiv:2604.20938）&quot;">​</a></h3><p><strong>對 §2 缺口分析（observability）的補完</strong>：現有 gate（measure.sh <code>--gate</code> / healthcheck）驗「byte / §R header / 結構」，但無「行為層 telemetry」。HARBOR 提供一個 pass-rate 看不見的 bug 偵測模式：</p><p><strong>接地審計</strong>：</p><ul><li>telemetry 模式 ← &quot;<strong>Telemetry counters</strong>: cache_hits, token_savings, reflections_written, reflections_retrieved, predictions_fired — enables silent bug detection via read/write asymmetry.&quot;（2026-04-22-harbor-automated-harness-optimization-2604-20938.md L100）</li><li>實例 ← &quot;<code>reflections_written=80, reflections_retrieved=0</code> → container non-persistence&quot;（同檔 L126）</li><li>安全約束 ← &quot;HARBOR&#39;s safety constraint (posterior chance constraint) is directly analogous to <code>autoresearch</code>&#39;s Guard: discard changes whose lower bound violates the safety margin.&quot;（同檔 L165）</li></ul><p><strong>啟示</strong>：未來若建 memory/skill 用量遙測（如 MEMORY 寫入 vs 召回計數），讀寫不對稱（written&gt;0 但 retrieved=0）能抓出「寫了沒人讀 = 孤兒」的靜默缺陷——正是 MEMORY Lesson E「manual-read ref 孤兒 = 死重」的可遙測化。<strong>落點</strong>：非本 loop（須先有遙測基礎設施），記為 G-D 類 out-of-band 增建。</p><h3 id="補充-g-g-harness-改進需-structured-semantic-observability-ahe-arxiv-2604-25850" tabindex="-1">補充 G-G：harness 改進需 structured semantic observability（AHE，arXiv:2604.25850） <a class="header-anchor" href="#補充-g-g-harness-改進需-structured-semantic-observability-ahe-arxiv-2604-25850" aria-label="Permalink to &quot;補充 G-G：harness 改進需 structured semantic observability（AHE，arXiv:2604.25850）&quot;">​</a></h3><p><strong>對 OBSERVE 階段的學術接地</strong>：</p><p><strong>接地審計</strong>：</p><ul><li>定義 ← &quot;Observability is not just logging — it is structured semantic tracing that enables systematic harness improvement. Without observability, harness engineering is artisanal; with it, it becomes engineering.&quot;（2026-04-30-ahe-observability-driven-harness-2604-25850.md L163）</li><li>量化 ← &quot;ten AHE iterations improved pass@1 from 69.7% to 77.0%&quot;（同檔 L24）</li></ul><p><strong>啟示</strong>：本藍圖的 measure.sh/healthcheck 屬「功能/結構」可觀測，但 §R 遵守度（behavioral）仍須 out-of-band per-model session（T3 已 defer）。AHE 印證「無結構化語意追蹤 → harness 改進是手工藝」——強化 G-D（task-07/08 behavioral verdict）的必要性，但不改本 loop 終態判定。</p><h3 id="補充-g-h-自動化-skill-學習有-30-天花板-人寫-gate-不可省-skilllearnbench-arxiv-2604-20087" tabindex="-1">補充 G-H：自動化 skill 學習有 ~30% 天花板，人寫 gate 不可省（SkillLearnBench，arXiv:2604.20087） <a class="header-anchor" href="#補充-g-h-自動化-skill-學習有-30-天花板-人寫-gate-不可省-skilllearnbench-arxiv-2604-20087" aria-label="Permalink to &quot;補充 G-H：自動化 skill 學習有 ~30% 天花板，人寫 gate 不可省（SkillLearnBench，arXiv:2604.20087）&quot;">​</a></h3><p><strong>對「測試什麼 / 誰來 gate」的接地</strong>：</p><p><strong>接地審計</strong>：</p><ul><li><code>~30%</code> ceiling vs <code>74.50%</code> human ← &quot;Human-authored skills: 74.50%. Automated skill-learning methods: ~30% (ceiling).&quot;（2026-04-22-skill-learn-bench-continual-skill-learning-2604-20087.md L20）</li><li>外部回饋 &gt; 自我回饋 ← &quot;External feedback outperforms self-feedback for skill refinement.&quot;（同檔 L20）</li></ul><p><strong>啟示</strong>：呼應本藍圖核心修正「測試只 stage protection 不 deliver，§R re-encode 須 user gate」——<strong>自動化（self-feedback）有上限，人類 gate（external feedback）是品質來源</strong>。直接背書「§R 調整一次一條 + user gate」的設計，非過度保守。</p><p><em>增量併入日期：2026-06-05 | gap-vote 3 真 gap（HARBOR-telemetry / AHE-observability / SkillLearnBench-human-gate）| 全數主對話親自 grep 接地 | 皆 out-of-band 增建接地，不改本 loop 終態（T1/T2/T3 仍綠）</em></p>',51)])])}const p=e(s,[["render",d]]);export{g as __pageData,p as default};
